const BUTTON_FONT_SIZE: f32 = 16.0;
const BACKGROUND_COLOR: (f32, f32, f32, f32) = (0.0, 0.0, 0.0, 1.0);
const TITLE_COLOR: (f32, f32, f32, f32) = (1.0, 1.0, 1.0, 1.0);

fn main() {
    env::set_var("WGPU_INSTANCE_EXPOSE_WEBGL_LAYER", "1");
