    let (tx, rx) = mpsc::channel();
    let thread = tokio::spawn(async move {
        let mut builder = Builder::new(rx);
        let mut theme = Theme::new();
        let layout = Layout::new();
        let title = Text::new("YouTube", TITLE_FONT_SIZE, TITLE_COLOR);
        let description = Text::new("Your channel description", DESCRIPTION_FONT_SIZE, (0.5, 0.5, 0.5, 1.0));
        let image = Image::new(Path::new("path/to/image.jpg"));
        let button1 = Button::new("Subscribe", BUTTON_FONT_SIZE, (1.0, 1.0, 1.0, 1.0));
        let button2 = Button::new("Sign in", BUTTON_FONT_SIZE, (1.0, 1.0, 1.0, 1.0));
        let mut column = Column::new();
        column.push(title);
        column.push(description);
        column.push(image);
        column.push(button1);
        column.push(button2);
        let render_pass = device.create_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("Render Pass"),
            color_attachments: &[wgpu::RenderPassColorAttachment {
                view: &layout.view,
                resolve_target: None,
                load_op: wgpu::LoadOp::Clear,
                store_op: wgpu::StoreOp::Store,
                clear_color: BACKGROUND_COLOR,
            }],
            depth_stencil_attachment: None,
        });
        loop {
            let events = layout.poll_events();
            for event in events {
                tx.send(event).unwrap();
                match event {
                    wgpu_ui::Event::ButtonClicked(button) => {
                        if button == &button1 {
                            println!("Subscribe button clicked");
                        } else if button == &button2 {
                            println!("Sign in button clicked");
                        }
                    }
                    _ => {}
                }
            }
            render_pass.execute(&layout.layout);
            layout.draw();
        }
    });
    tokio::select! {
        _ = thread => todo!("thread finished"),
        event = tx.recv() => {
            match event {
                wgpu_ui::Event::MouseMoved { x, y } => {
                    println!("Mouse moved to ({}, {})", x, y);
                }
                wgpu_ui::Event::Resized { width, height } => {
                    println!("Window resized to ({}, {})", width, height);
                }
                wgpu_ui::Event::Closed => {
                    println!("Window closed");
                    break;
                }
                _ => {}
            }
        }
    }
    queue.submit(&[device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
        label: Some("Root Stage"),
    })]).await.unwrap();
    surface.destroy();
    window.close();
}

fn create_window() -> (Window, Surface, Instance, Adapter, Device, Queue) {
